pub(crate) fn check_reference_opened(opened: &str) -> String {
    if opened == ".as_deref()" { return String::from(".as_deref()"); }
    String::from(".as_ref()")
}

pub(crate) fn check_reference_written(expr: &Expr) -> bool {
    match expr {
        Expr::Unary { op, .. } => matches!(op, UnaryOp::Ref),
        _ => false,
    }
}

pub(crate) fn check_reference_nullable(ty: &Ty) -> bool { matches!(ty, Ty::Nullable(_)) }

pub(crate) fn check_reference_nullable_view(ty: &Ty) -> bool {
    match ty {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); inner.is_a_view() },
        _ => false,
    }
}

